CREATE TABLE ezcobj_state (id INT AUTO_INCREMENT NOT NULL, default_language_id BIGINT DEFAULT 0 NOT NULL, group_id INT DEFAULT 0 NOT NULL, identifier VARCHAR(45) DEFAULT '' NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, priority INT DEFAULT 0 NOT NULL, INDEX ezcobj_state_priority (priority), INDEX ezcobj_state_lmask (language_mask), UNIQUE INDEX ezcobj_state_identifier (group_id, identifier), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
